// Enrichissement éditorial Lore — couche de preview sur preview/lore.
// Le corpus compressé reste inchangé ; cette couche remplace les entrées trop sèches
// et nettoie les formulations éditoriales avant qu’un brouillon local ne soit appliqué.
const SECTION_PATCHES={"agences::services-etrangers":[{"title":"Le renseignement hors de Grande Californie","blocks":[{"text":"Les grands services de renseignement ont survécu à l’effondrement de l’ancien ordre international, mais rarement sans se transformer. Certains sont devenus des pouvoirs politiques presque autonomes, d’autres vendent leurs compétences, se sont rapprochés des corporations ou ont redéfini leur mission autour de l’information médiatique et économique.","type":"p"},{"text":"La CIA américaine agit désormais comme un arbitre majeur autour de la présidence fédérale ; le SVR russe fonctionne largement comme un renseignement mercenaire ; le MI6 britannique s’est recentré sur l’information et la vérification médiatique ; la DGSE française défend une marge d’autonomie face aux corporations ; le Naicho japonais s’est corporatisé autour de l’UniFate ; le Mossad conserve enfin une forte autonomie tout en étant traversé par les réseaux politiques, familiaux et corporatifs israéliens.","type":"p"},{"text":"Pour le CBII et le CNAD, ces services sont autant des partenaires que des rivaux. Une coopération ponctuelle n’efface jamais la concurrence pour les sources, les opérations clandestines ni la lecture politique des mêmes événements.","type":"p"}]}],"angelus::sephira-kether":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la domination, la conscience, l’unité","type":null},{"text":"Archanges créés : Remiel","type":null},{"text":"Démons sacrifices : Belial","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Kether exprime l’autorité qui rassemble plutôt que la simple domination. La conscience et l’unité y deviennent des forces sacrées : celui qui ouvre ce Sephira impose une cohérence au monde qui l’entoure, qu’elle soit protectrice, politique ou spirituelle. Remiel et Metatron en représentent deux manifestations majeures.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"01. Sephira Kether : Remiel","type":null},{"text":"11. Sephira Kether : Metatron","type":null}]}],"angelus::sephira-hokhma":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la sagesse, la pureté, la magie","type":null},{"text":"Archanges créés : Raziel","type":null},{"text":"Démons sacrifices : Mephisto","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Ḥokhma incarne la connaissance qui transforme. Sa sagesse n’est pas seulement intellectuelle : elle purifie, révèle et donne une forme à la magie. Raziel en est l’expression la plus naturelle, gardien d’un savoir capable d’éclairer autant que de consumer ceux qui le recherchent sans préparation.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"02. Sephira Ḥokhma : Raziel","type":null}]}],"angelus::sephira-bina":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : l’intelligence, le destin, les limitations","type":null},{"text":"Archanges créés : Zaphkiel","type":null},{"text":"Démons sacrifices : Mammon","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Bina donne une forme au possible. L’intelligence y rencontre le destin et les limites : comprendre une chose, c’est aussi reconnaître ce qu’elle peut devenir et ce qu’elle ne pourra jamais dépasser. Zaphkiel porte cette dimension de discernement, de mesure et de fatalité.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"03. Sephira Bina : Zaphkiel","type":null}]}],"angelus::sephira-hesed":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la miséricorde, la guérison, la créativité","type":null},{"text":"Archanges créés : Zadkiel","type":null},{"text":"Démons sacrifices : Beelzebuth","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Hesed est le Sephira de ce qui restaure et permet de recommencer. La miséricorde, la guérison et la créativité y procèdent du même principe : refuser que la blessure, la faute ou la destruction soient toujours définitives. Zadkiel en incarne la puissance réparatrice.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"04. Sephira Hesed : Zadkiel","type":null}]}],"angelus::sephira-gueburah":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la force, la justice, la guerre","type":null},{"text":"Archanges créés : Camael","type":null},{"text":"Démons sacrifices : Satan","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Gueburah est la force qui tranche. Guerre et justice y sont liées par l’idée qu’un ordre doit parfois être défendu par la contrainte, au risque de confondre discipline et brutalité. Camael incarne cette puissance de décision, redoutable lorsqu’elle cesse de douter de son propre droit à frapper.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"05. Sephira Gueburah : Camael","type":null}]}],"angelus::sephira-tiphereth":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la foi, la dévotion, le sacrifice","type":null},{"text":"Archanges créés : Michael","type":null},{"text":"Démons sacrifices : Baal","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Tiph'ereth unit beauté, foi et sacrifice autour d’une même exigence : donner de soi à quelque chose de plus grand. Cette logique peut produire l’héroïsme comme le fanatisme. Michael en représente la forme la plus lumineuse, celle d’une dévotion qui accepte de payer personnellement le prix de ce qu’elle défend.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"06. Sephira Tiph'ereth : Michael","type":null}]}],"angelus::sephira-nesah":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : le succès, l’amour, la sexualité","type":null},{"text":"Archanges créés : Haniel","type":null},{"text":"Démons sacrifices : Lilith","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Nesah gouverne l’élan qui pousse les êtres à vouloir, séduire, aimer et triompher. Son domaine touche autant au désir qu’à la persévérance : réussir suppose de maintenir une volonté dans le temps. Haniel en exprime la dimension de grâce, tandis que le sacrifice de Lilith rappelle combien désir et victoire peuvent devenir possession.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"07. Sephira Nesah : Haniel","type":null}]}],"angelus::sephira-hod":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la gloire, la science, la connaissance","type":null},{"text":"Archanges créés : Raphaël","type":null},{"text":"Démons sacrifices : Astaroth","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Hod est le Sephira de la connaissance rendue visible. Science, gloire et compréhension y sont liées par la capacité à formuler, transmettre et démontrer. Raphaël en incarne une lecture où le savoir doit servir, guérir et ordonner le monde plutôt que simplement distinguer celui qui le possède.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"08. Sephira Hod : Raphaël","type":null}]}],"angelus::sephira-yessod":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : les rêves, l’illusion, l’imagination","type":null},{"text":"Archanges créés : Gabriel","type":null},{"text":"Démons sacrifices : Diablo","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Yessod donne consistance à ce qui n’existe d’abord que dans l’esprit. Rêves, illusions et imagination ne sont pas de simples tromperies : ils forment la fondation invisible à partir de laquelle les êtres interprètent puis transforment le réel. Gabriel porte cette puissance de révélation autant que de mise en scène.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"09. Sephira Yessod : Gabriel","type":null}]}],"angelus::sephira-malkhouth":[{"title":"Sephira","blocks":[{"text":"Pouvoirs associés : la mort, le monde physique, le poids","type":null},{"text":"Archanges créés : Sandalphon","type":null},{"text":"Démons sacrifices : Morrighan","type":null}]},{"title":"Sens du Sephira","blocks":[{"text":"Malkhouth est le point où le spirituel rencontre la matière. Le poids, le monde physique et la mort y rappellent que toute volonté finit par prendre corps, rencontrer une limite et laisser une trace. Sandalphon en représente l’ancrage : un pouvoir moins éclatant que d’autres Sephiroth, mais directement lié à ce qui rend le monde tangible.","type":null}]},{"title":"Manifestations connues","blocks":[{"text":"10. Sephira Malkhouth : Sandalphon","type":null}]}],"anti-systemes::hell-angels":[{"title":"Implantation et identité","blocks":[{"text":"Les Hell Angels restent l’un des clubs de motards les plus emblématiques de l’Underlife californienne. Leur puissance tient moins à une structure mafieuse classique qu’à un réseau de chapitres soudés, implantés le long des grands axes et dans les zones rurales où l’autorité urbaine se fait plus distante.","type":null},{"text":"Ils cultivent une réputation d’indépendance farouche et refusent volontiers de se placer sous la coupe d’une grande organisation criminelle. Leur rivalité avec les Cruisers résume leur identité : là où ces derniers privilégient les réseaux urbains et logistiques, les Hell Angels revendiquent la route, le territoire et l’autonomie des chapitres.","type":null}]},{"title":"Culture de club","blocks":[{"text":"Le club valorise la loyauté interne, la capacité à encaisser les conflits et une vision presque patrimoniale de ses routes et de ses implantations. Les dirigeants locaux comptent souvent davantage par leur ancienneté et leur capacité à maintenir la cohésion que par un titre formel.","type":null}]}],"anti-systemes::cruisers":[{"title":"Implantation et identité","blocks":[{"text":"Les Cruisers forment le grand pôle urbain du monde biker californien. Là où les Hell Angels s’appuient volontiers sur la route, les zones rurales et l’autonomie des chapitres, les Cruisers ont construit leur influence autour des métropoles, des garages, des circuits de transport et des réseaux logistiques de l’Underlife.","type":null},{"text":"Leur puissance vient de leur capacité à faire circuler personnes, pièces, véhicules et marchandises entre des milieux qui se méfient les uns des autres. Un chapitre Cruiser peut donc être moins visible qu’un gang de rue tout en disposant d’un poids considérable dans l’économie clandestine locale.","type":null}]},{"title":"Rivalités","blocks":[{"text":"La rivalité avec les Hell Angels n’est pas seulement une guerre de couleurs : elle oppose deux manières de concevoir le monde biker. Les Cruisers privilégient la densité des réseaux et l’accès aux villes ; leurs adversaires mettent davantage en avant la souveraineté des chapitres et le contrôle des routes.","type":null}]}],"anti-systemes::reapers-inc":[{"title":"D’un gang à un club","blocks":[{"text":"Reapers Incorporated Power est né de la culture de rue avant d’adopter progressivement les codes des Motorcycle Clubs. Cette origine hybride reste visible dans son esthétique, ses recrutements et son rapport à la violence : le club se comporte moins comme une vieille confrérie biker que comme une organisation urbaine ayant découvert dans la moto un moyen d’étendre son territoire.","type":null},{"text":"Ses chapitres mêlent culture punk, débrouille mécanique et réflexes de gang. Cette identité attire des membres plus jeunes ou plus instables que dans les clubs historiques, mais elle donne aussi aux Reapers une capacité à s’adapter rapidement aux transformations de l’Underlife.","type":null}]},{"title":"Organisation","blocks":[{"text":"Le nom « Incorporated Power » résume assez bien leur culture : chaque chapitre cherche à peser localement tout en restant relié à une marque commune. Le pouvoir se gagne par l’action, la réputation et la capacité à tenir un groupe soudé dans des environnements hostiles.","type":null}]}],"anti-systemes::vagos":[{"title":"Un club de frontière","blocks":[{"text":"Les Vagos sont profondément marqués par le Sud californien et les territoires frontaliers. Leur histoire les a placés au contact des trafics mexicains, des communautés hispaniques et des conflits de routes qui structurent une partie de l’économie clandestine entre Grande Californie et Mexique.","type":null},{"text":"Le club a progressivement abandonné plusieurs marqueurs suprémacistes de son ancienne culture pour devenir plus largement hispanisé. Cette transformation n’a pas rendu les Vagos plus pacifiques ; elle a surtout déplacé leur identité vers la solidarité de quartier, le contrôle des axes de passage et une proximité fluctuante avec les cartels.","type":null}]},{"title":"Position dans l’Underlife","blocks":[{"text":"Les Vagos vivent dans une zone grise entre club autonome et partenaire criminel. Ils peuvent travailler avec des organisations plus puissantes sans accepter de devenir leur simple bras armé, ce qui les rend utiles mais difficiles à contrôler.","type":null}]}],"anti-systemes::sons-of-silence":[{"title":"Un club militarisé","blocks":[{"text":"Les Sons of Silence se distinguent par une culture plus militaire que la plupart des grands clubs bikers. Les guerres de chapitres et les pertes accumulées ont renforcé chez eux l’idée qu’un club doit survivre comme une unité combattante : discipline, préparation et solidarité interne y pèsent davantage que le folklore de la route.","type":null},{"text":"Les pertes parmi les anciens cadres ont aussi modifié la place des femmes dans l’organisation. Là où les clubs historiques les maintiennent souvent dans des rôles périphériques, plusieurs chapitres des Sons of Silence ont vu émerger des membres et dirigeantes capables d’occuper directement des responsabilités opérationnelles.","type":null}]},{"title":"Réputation","blocks":[{"text":"Cette évolution leur donne une image froide et pragmatique. Ils ne sont pas nécessairement les plus nombreux, mais peu d’adversaires sous-estiment leur capacité à préparer un conflit ou à maintenir un chapitre fonctionnel après de lourdes pertes.","type":null}]}],"anti-systemes::sons-of-legba":[{"title":"Origines et culture","blocks":[{"text":"Les Sons of Legba ont été fondés autour d’anciens militaires noirs qui cherchaient autant une communauté qu’une structure de défense. Leur culture mêle solidarité de route, fierté communautaire et une forte tradition de médiation : le club préfère souvent négocier un passage ou arbitrer un conflit avant de démontrer qu’il sait aussi se battre.","type":null},{"text":"Le nom et l’imagerie de Legba ont donné au club une esthétique fortement inspirée du vaudou et de différents néopaganismes afro-caribéens. Cette symbolique n’impose pourtant pas une religion commune ; elle fonctionne surtout comme un langage de seuil, de voyage et de passage, parfaitement adapté à un club dont l’identité repose sur la route.","type":null}]},{"title":"Place dans l’Underlife","blocks":[{"text":"Leur capacité à circuler entre communautés en fait des intermédiaires recherchés. Les Sons of Legba peuvent servir de relais entre des groupes qui refusent de se parler directement, mais leur neutralité n’est jamais gratuite : elle dépend du respect accordé au club et de la confiance construite avec ses chapitres.","type":null}]}],"anti-systemes::onikishi":[{"title":"Les démons de la route","blocks":[{"text":"Les Onikishi sont issus de réseaux de vétérans et de communautés asiatiques qui ont reconstruit une identité biker autour d’une esthétique de samouraïs modernes. Armures stylisées, emblèmes démoniaques et discipline de groupe leur donnent une apparence immédiatement reconnaissable dans l’Underlife.","type":null},{"text":"Cette imagerie n’est pas qu’un décor. Le club valorise le devoir envers le groupe, la maîtrise de soi et une conception codifiée de l’honneur, même si ces principes sont adaptés au monde criminel et aux réalités de la route plutôt qu’à une tradition historique pure.","type":null}]},{"title":"Organisation","blocks":[{"text":"Les chapitres Onikishi tendent à être plus structurés et plus ritualisés que ceux de nombreux rivaux. Cette discipline leur vaut autant le respect que la méfiance : ils donnent l’impression d’une confrérie capable de transformer une querelle de rue en conflit durable si son honneur collectif est publiquement atteint.","type":null}]}],"anti-systemes::last-crows":[{"title":"Un club itinérant","blocks":[{"text":"Les Last Crows comptent parmi les clubs les plus nomades de Grande Californie. Leur identité repose moins sur la possession d’un quartier ou d’un territoire fixe que sur la capacité à se déplacer, maintenir des relais et revenir régulièrement dans des régions très éloignées les unes des autres.","type":null},{"text":"Le club rassemble de nombreux membres issus des nations amérindiennes, sans pour autant se confondre avec une organisation politique autochtone. Cette composition nourrit une culture de route où les récits, les signes et les traditions locales ont davantage de poids que dans les clubs purement urbains.","type":null}]},{"title":"Aux frontières du surnaturel","blocks":[{"text":"Les Last Crows sont régulièrement associés à des histoires de chasse, de folklore et d’événements étranges. Tous leurs membres ne connaissent pas la Vérité, mais le club a suffisamment croisé de phénomènes occultes pour que certaines de ses routes et de ses habitudes paraissent incompréhensibles aux simples gangs criminels.","type":null}]}],"anti-systemes::underwater-nation":[{"title":"Une nation sous la surface","blocks":[{"text":"Underwater Nation désigne des communautés autonomes installées dans des structures maritimes, submersibles ou semi-submersibles et organisées autour d’une idée simple : l’océan peut offrir un territoire hors de portée des États et des corporations.","type":null},{"text":"Cette autonomie les place naturellement en conflit avec l’exploitation industrielle des mers. Les plateformes, fermes océaniques et opérations d’extraction sont perçues moins comme des opportunités économiques que comme l’extension d’un ordre terrestre dont les membres d’Underwater Nation cherchent précisément à s’affranchir.","type":null}]},{"title":"Culture","blocks":[{"text":"La vie y exige une forte discipline collective : énergie, air, eau, réparations et évacuations ne peuvent pas être abandonnés aux improvisations individuelles. Leur anti-système est donc paradoxalement très organisé, fondé sur l’autonomie technique et la responsabilité envers l’habitat commun.","type":null}]}],"anti-systemes::gold-cow-kingdom":[{"title":"Autonomie agricole","blocks":[{"text":"Gold Cow Kingdom rassemble des communautés rurales et survivalistes qui ont choisi de réduire au minimum leur dépendance aux grandes villes, aux réseaux corporatifs et aux chaînes logistiques modernes. Leur richesse se mesure moins en crédits qu’en terres, cheptels, ateliers et capacité à tenir plusieurs mois sans aide extérieure.","type":null},{"text":"Ils commercent avec le reste de la Grande Californie, mais cherchent à ce que cet échange ne devienne jamais une dépendance. Les technologies qu’ils acceptent sont celles qu’ils peuvent entretenir, réparer ou remplacer localement, ce qui donne à leurs implantations un mélange de rusticité assumée et de pragmatisme technique.","type":null}]},{"title":"Le « royaume »","blocks":[{"text":"Le nom de Kingdom relève autant de la provocation que de l’identité communautaire. Chaque implantation défend une souveraineté quotidienne très concrète : décider de son travail, de sa production et de ses règles locales sans qu’une administration lointaine ou une corporation dicte l’organisation du territoire.","type":null}]}],"anti-systemes::true-nations":[{"title":"Souveraineté radicale","blocks":[{"text":"True Nations regroupe des communautés et militants autochtones qui considèrent que l’autonomie concédée par les États reste insuffisante tant qu’elle dépend de lois et de frontières imposées de l’extérieur. Leur anti-système repose sur une lecture radicale de la souveraineté : une nation n’a pas à demander la permission d’exister.","type":null},{"text":"Le mouvement se distingue des Native Old Blood et d’autres réseaux traditionnels par son refus plus net du compromis institutionnel. Cette ligne n’empêche pas les alliances locales, mais elle rend toute coopération fragile dès qu’elle peut être interprétée comme une reconnaissance de l’autorité californienne ou fédérale.","type":null}]},{"title":"Identité politique","blocks":[{"text":"True Nations n’est pas un bloc ethnique uniforme. Les communautés qui s’en réclament peuvent avoir des cultures, des objectifs et des pratiques très différentes ; elles partagent surtout la conviction que la survie culturelle exige parfois de sortir des cadres juridiques dans lesquels les gouvernements veulent les enfermer.","type":null}]}],"anti-systemes::green-fairy-daughters":[{"title":"Quitter les mégacités","blocks":[{"text":"Les Green Fairy Daughters représentent la branche communautaire et ender d’un environnement plus large lié aux Green Fairy. Là où certains militants cherchent encore à transformer les villes, elles considèrent qu’une partie de la population doit pouvoir s’en extraire et construire autre chose hors de la dépendance métropolitaine.","type":null},{"text":"Leurs implantations privilégient l’autonomie énergétique, la récupération, l’agriculture locale et des structures de décision de petite taille. La technologie n’y est pas rejetée : elle est triée selon sa capacité à renforcer l’indépendance plutôt qu’à recréer les mêmes dépendances envers les grandes plateformes et les corporations.","type":null}]},{"title":"Réseaux","blocks":[{"text":"Les communautés restent reliées entre elles et aux réseaux écologistes urbains. Cette circulation de personnes, de matériel et d’informations permet aux Green Fairy Daughters d’éviter l’isolement complet tout en maintenant une forte méfiance envers les institutions qui veulent transformer leur autonomie en programme administratif.","type":null}]}],"anti-systemes::green-nomads":[{"title":"Le village en mouvement","blocks":[{"text":"Les Green Nomads ont poussé l’idée d’autonomie jusqu’à refuser le territoire fixe. Leurs communautés se déplacent en convois capables de transporter habitat, ateliers, réserves et systèmes énergétiques, formant des villages temporaires qui peuvent disparaître avant qu’une autorité ne transforme leur présence en implantation permanente.","type":null},{"text":"Ils privilégient des technologies robustes, réparables et peu dépendantes des réseaux de communication. La faible connectivité n’est pas un retard : elle limite la surveillance, la traçabilité et la dépendance à des infrastructures contrôlées par d’autres.","type":null}]},{"title":"Défense","blocks":[{"text":"Un convoi mobile est vulnérable s’il ne peut pas se défendre. Les Green Nomads assument donc une culture plus armée que de nombreuses communautés écologistes, avec des membres chargés de protéger les véhicules, de reconnaître les routes et d’éviter que la mobilité ne devienne synonyme de fuite permanente.","type":null}]}],"anti-systemes::fermes-mannan":[{"title":"Communautés rurales","blocks":[{"text":"Les Fermes Mannan sont des communautés rurales qui ont transformé l’exploitation agricole familiale en modèle d’autonomie locale. La ferme n’y est pas seulement un lieu de production : elle devient un noyau social, un atelier, un refuge et parfois une petite communauté capable d’absorber plusieurs familles.","type":null},{"text":"Leur anti-système est moins spectaculaire que celui des groupes armés ou des squats urbains. Il repose sur la capacité à produire, réparer et échanger localement suffisamment de choses pour que ni une crise ni une décision corporative ne puisse immédiatement mettre la communauté à genoux.","type":null}]},{"title":"Réseaux d’échange","blocks":[{"text":"Les Fermes Mannan ne vivent pas en autarcie absolue. Elles constituent plutôt un maillage de producteurs indépendants qui s’échangent semences, pièces, services et main-d’œuvre, donnant au monde rural une résilience que les grands circuits de distribution ont du mal à contrôler complètement.","type":null}]}],"anti-systemes::mola-mola":[{"title":"Communauté maritime","blocks":[{"text":"Mola Mola est une communauté ender tournée vers la mer, organisée autour d’une culture volontairement informelle et hédoniste. Elle attire ceux qui veulent vivre loin de la discipline des grandes organisations sans renoncer pour autant à une véritable solidarité collective.","type":null},{"text":"La liberté individuelle y est valorisée tant qu’elle ne met pas en danger la communauté. Cette règle simple produit une justice essentiellement collective : les conflits sont arbitrés par ceux qui vivent ensemble plutôt que renvoyés vers une administration extérieure.","type":null}]},{"title":"Identité","blocks":[{"text":"Le groupe cultive une image presque légère, faite de mer, de fêtes et de débrouille. Cette décontraction masque une organisation capable de maintenir des embarcations, des habitats et des réseaux d’approvisionnement dans un environnement où la moindre erreur technique peut devenir mortelle.","type":null}]}],"anti-systemes::losttown":[{"title":"Une ville sous la ville","blocks":[{"text":"Losttown est une cité autonome dissimulée sous l’est de Los Angeles, née de l’accumulation de squats, de tunnels, de structures abandonnées et de communautés qui ne voulaient plus dépendre des institutions de surface. Avec le temps, l’assemblage est devenu un véritable territoire habité plutôt qu’un simple refuge clandestin.","type":null},{"text":"L’endroit est souvent cité comme preuve qu’une société peut exister en dehors de l’ordre municipal, mais rarement comme une utopie. L’absence d’autorité centrale forte laisse de la place aux solidarités locales autant qu’aux gangs, aux rapports de force et aux petits pouvoirs qui prospèrent lorsqu’aucune institution commune ne peut les contenir durablement.","type":null}]},{"title":"Un contre-exemple ender","blocks":[{"text":"Losttown sert donc autant de symbole que d’avertissement. Les Enders y voient la possibilité concrète de bâtir hors du système ; leurs adversaires y voient la démonstration que l’autonomie sans institutions partagées peut simplement remplacer une domination lointaine par plusieurs dominations de proximité.","type":null}]}],"corporations::nymphrover-corporation":[{"title":"Positionnement","blocks":[{"text":"Nymphrover s’est fait une place parmi les Manucorpos par la construction de navires de très grande taille et de forte puissance. Cette spécialisation l’a rapprochée des acteurs qui exploitent les océans à l’échelle industrielle.","type":null},{"text":"Ocean Master fait régulièrement appel à ses bâtiments pour soutenir ses plateformes, ses activités de pêche, ses fermes d’algues et ses opérations de retraitement maritime. Nymphrover apparaît ainsi moins comme une puissance politique autonome que comme un fournisseur industriel capable de rendre possibles les ambitions maritimes des plus grandes corporations.","type":null}]}],"corporations::owl-corporation":[{"title":"Positionnement","blocks":[{"text":"Owl s’est imposée comme un acteur majeur de l’armement au point de concurrencer directement Raven Industries, Phoenix et Byron Industries. Ses produits circulent aussi bien dans les guerres corporatistes que dans les mains d’acteurs clandestins.","type":null},{"text":"Lors de la guerre financière menée au Mexique, les troupes d’élite des narcotrafiquants équipées par Owl infligèrent de lourdes pertes aux forces corporatives. En 2034, la montée d’Owl contribue également à reléguer Phoenix derrière les premiers fabricants mondiaux, faisant de la corporation un concurrent que les anciennes puissances de l’armement ne peuvent plus traiter comme un simple outsider.","type":null}]}],"daemon-temples::temple-morrighan":[{"title":"Un temple à part","blocks":[{"text":"Le Temple de Morrighan est atypique parmi les Temples daemoniaques. Morrighan vient d’Aèr, où elle fut reine des dieux avant de quitter ce monde, puis elle obtint sur Terre un rang divin et des serviteurs sans posséder pour autant un Enfer personnel comparable à ceux des anciens dieux terrestres.","type":null},{"text":"Son sanctuaire concentre donc moins la logique d’un royaume infernal que celle d’un point d’ancrage pour ses esprits. Guerre, mort, royauté et magie s’y mêlent, avec une présence récurrente des corvidés et des présages. Les serviteurs de Morrighan conservent cette étrangeté : à leur mort, ils peuvent recevoir une forme animale ou végétale dans laquelle revenir sur Terre.","type":null}]}],"daemon-temples::temple-belial":[{"title":"Le cœur du pouvoir de Belial","blocks":[{"text":"Le Cabinet Faith constitue le Temple de Belial dans la Réalité, et le bureau de Belial elle-même en est le portail infernal. Le sanctuaire prend ainsi la forme d’un lieu de pouvoir parfaitement intégré au monde moderne plutôt que celle d’un édifice religieux visible.","type":null},{"text":"Belial règne sur le feu, la royauté et la destruction. Son Temple est à son image : il sert autant de cour que de forteresse et de centre de commandement pour la reine des dieux. L’épisode où Caïn força le Prophète de la Force, arraché à Baal, à prendre place sur un de ses trônes montre jusqu’où les rivalités entre Temples peuvent aller lorsque les Attributs sont en jeu.","type":null}]}],"daemon-temples::temple-lilith":[{"title":"Le sanctuaire du désir","blocks":[{"text":"Les studios de Redwheels forment le Temple de Lilith. Le choix n’a rien d’accidentel : Lilith règne sur l’amour, le désir, la beauté, la fertilité et la dévotion, et son culte prospère partout où les fantasmes, l’attention et les passions humaines deviennent une force collective.","type":null},{"text":"Le Temple brouille volontairement la frontière entre commerce, spectacle, intimité et religion. Beaucoup de mortels peuvent y participer sans jamais comprendre la nature réelle du lieu, tandis que les serviteurs de Lilith y trouvent un terrain idéal pour attirer, éprouver ou lier ceux dont les désirs sont assez puissants pour devenir une porte.","type":null}]}],"daemon-temples::temple-alabor":[{"title":"Le sanctuaire des eaux","blocks":[{"text":"Alabor règne sur l’eau, la mer, la pluie, le chaos et la fertilité. Son Temple est donc moins défini par une architecture précise que par son rapport à un territoire hydraulique ou maritime : bassins, réseaux d’eau, structures portuaires et lieux soumis aux marées peuvent devenir autant de prolongements de son domaine.","type":null},{"text":"Ses serviteurs privilégient les lieux où l’eau façonne directement la vie humaine. La fertilité d’Alabor n’a rien de paisible : elle appartient au même cycle que les tempêtes, les inondations et les courants qui nourrissent une côte avant de la détruire.","type":null}]}],"daemon-temples::temple-mammon":[{"title":"Le sanctuaire du passage","blocks":[{"text":"Mammon règne sur la mort, l’âge, le destin et la délivrance. Son Temple n’est pas seulement un lieu funéraire : il est associé aux moments où une existence arrive à son terme, où une dette doit être soldée et où le temps cesse d’être négociable.","type":null},{"text":"La mort y est conçue comme une permission autant que comme une fatalité. Cette conception donne au Temple une atmosphère d’attente, de jugement silencieux et de passage, bien différente de la violence ouverte des sanctuaires liés à la guerre ou à la destruction.","type":null}]}],"daemon-temples::temple-diablo":[{"title":"Le sanctuaire de la peur","blocks":[{"text":"Diablo règne sur la nuit, l’ombre, les cauchemars et la peur. Son Temple prospère naturellement dans les lieux où la lumière est absente mais surtout là où l’imagination transforme cette absence en menace.","type":null},{"text":"Ses daemons imitent une partie des pouvoirs des Ombres et des vampires, ce qui renforce la confusion entre prédateur nocturne, créature de la Vérité et serviteur divin. Le Temple exploite cette ambiguïté : la peur fonctionne d’autant mieux que la victime ne sait pas encore ce qu’elle doit craindre.","type":null}]}],"daemon-temples::temple-astaroth":[{"title":"Le sanctuaire de la connaissance","blocks":[{"text":"Astaroth règne sur la sagesse, l’intelligence, l’écriture, les arts et la civilisation. Son Temple prend naturellement la forme d’un lieu où le savoir est accumulé, produit, classé ou transmis : bibliothèque, archive, institution savante ou collection peuvent devenir des espaces sacrés à ses yeux.","type":null},{"text":"Les serviteurs d’Astaroth peuvent assimiler un savoir écrit par simple contact, faisant de l’archive une forme de puissance immédiate. Leur culte valorise donc moins la possession ostentatoire d’un secret que la capacité à absorber, relier et exploiter des connaissances que les mortels mettent parfois des vies à acquérir.","type":null}]}],"daemon-temples::temple-satan":[{"title":"Le sanctuaire du jugement","blocks":[{"text":"Satan règne sur la justice, l’ordre, la paix et la vengeance. Son Temple se construit autour d’une contradiction permanente : maintenir l’ordre exige parfois de punir, et la frontière entre justice et vengeance dépend de celui qui prononce la sentence.","type":null},{"text":"Serments, arbitrages et condamnations y ont donc un poids particulier. Cette conception fait du Temple un lieu redouté même par d’autres serviteurs divins, car l’obéissance à Belial n’y efface pas la question de la faute.","type":null}]}],"daemon-temples::temple-mephisto":[{"title":"Le sanctuaire des mots et de l’occulte","blocks":[{"text":"Méphisto règne sur la magie, les chants, la parole, la chance, les illusions, les sciences et les malédictions. Son Temple est un lieu de savoir instable, où une formule, un récit ou une démonstration peut valoir autant qu’un rituel.","type":null},{"text":"Beaucoup de ses daemons furent autrefois des sorciers, des magiciens ou des Mages. Certains conservent même un spectre de Mageius leur donnant une affinité proche de celle d’un véritable Mage. La cour de Méphisto attire donc naturellement les praticiens pour qui la frontière entre recherche, mensonge et sorcellerie n’a jamais été très nette.","type":null}]}],"daemon-temples::temple-abigor":[{"title":"Un Temple fantôme des tempêtes","blocks":[{"text":"Abigor, déesse du ciel, des vents, de l’orage et des tempêtes, a perdu son Enfer lors de la guerre contre le Paradis. Son sanctuaire relève donc des Temples fantômes : il ne dispose plus de tout l’appareil d’un Temple daemoniaque intact et s’organise autour d’une relique capable de maintenir un ancrage divin.","type":null},{"text":"Ses serviteurs manient les vents et les gaz et ne peuvent être tués par suffocation ou inhalation toxique. Le culte d’Abigor conserve ainsi une identité verticale et violente, tournée vers le ciel, le châtiment et les phénomènes atmosphériques, même si sa puissance institutionnelle n’est plus celle d’une divinité victorieuse.","type":null}]}],"daemon-temples::temple-baal":[{"title":"Un Temple fantôme de la guerre","blocks":[{"text":"Baal, dieu des armes, de la guerre, de la stratégie, de la force et de la victoire, a été vaincu par le Paradis. Son ancien système infernal est brisé et son sanctuaire relève désormais des Temples fantômes, dépendant d’un ancrage matériel et de serviteurs prêts à maintenir son influence sans garantie de retour après leur mort.","type":null},{"text":"Le siège d’Ushkoll est un sombre-temple de la guerre et constitue l’un des lieux où l’influence de Baal trouve naturellement prise dans la Réalité. Les employés n’ont pas besoin d’être des cultistes : la concentration d’armes, d’entraînement, de violence organisée et de volonté de vaincre suffit à faire du lieu un puissant foyer pour ses daemons.","type":null}]}],"daemon-temples::temple-beelzebuth":[{"title":"Un Temple fantôme de la vie","blocks":[{"text":"Beelzebuth règne sur la vie, la nature, les animaux, la santé et la maladie. Vaincu par le Paradis, il ne possède plus un Temple complet : son culte survit autour d’ancrages capables de concentrer cette dualité entre abondance et corruption du vivant.","type":null},{"text":"Ses daemons peuvent disposer de plusieurs vies en sacrifiant une part de leur propre vigueur. Le Temple porte donc une conception très concrète de la survie : la vie n’y est jamais purement bienveillante, elle prolifère, se défend, tombe malade, guérit et exige parfois qu’une autre part d’elle-même soit consommée pour continuer.","type":null}]}],"daemon-temples::temple-lucifer":[{"title":"Un Temple fantôme solaire","blocks":[{"text":"Lucifer est l’ancien dieu de la lumière, du soleil, du jour, de la naissance et du courage. Sa défaite face au Paradis fut particulièrement sévère : ses attributs furent peu à peu absorbés par l’imaginaire angélique, au point que les mortels le décrivent plus volontiers comme un ange déchu que comme un ancien dieu terrestre.","type":null},{"text":"Son Temple fantôme est donc un sanctuaire de survivants. Ses daemons, devenus rares, restent particulièrement efficaces contre les Créatures telles que les Ombres et les vampires. Chaque manifestation de son culte cherche moins à bâtir une grande institution qu’à préserver une lumière divine que le Paradis a presque entièrement recouverte.","type":null}]}],"mage-lodges::loge-new-york":[{"title":"L’ancienne Haute Loge américaine","blocks":[{"text":"New-York représente l’ancien ordre magique des États-Unis. Avant la naissance de la Grande Californie, sa Haute Loge faisait partie des pôles qui fixaient les équilibres entre les cinq grandes villes américaines et elle considère la sécession californienne comme une rupture dangereuse de cet ordre.","type":null},{"text":"Lorsque Los Angeles revendique le statut de Haute Loge du nouvel État, New-York se rapproche de Mexico pour empêcher cette recomposition. La guerre qui en découle reste presque invisible pour les profanes : elle passe par les alliances, les influences, les déplacements de Mages et les affrontements occultes bien plus que par une guerre ouverte.","type":null}]}],"mage-lodges::loge-los-angeles":[{"title":"La Haute Loge de Grande Californie","blocks":[{"text":"Los Angeles s’est imposée comme le cœur politique des Mages de Grande Californie après sa victoire sur Tijuana. Cette victoire ne lui a pourtant pas donné une légitimité incontestée : elle a surtout transformé une grande loge urbaine en puissance nouvelle, née d’une guerre interne que le reste du monde magique n’a jamais complètement acceptée.","type":null},{"text":"La Loge de Los Angeles vit donc dans une culture de vigilance et de coalition. Elle doit tenir ensemble des Mages californiens aux origines très différentes tout en résistant à la pression de New-York et de Mexico, qui voient encore dans cette Haute Loge une sécession de plus au sein d’un monde magique déjà volontairement fragmenté.","type":null}]}],"mage-lodges::loge-san-diejuana":[{"title":"Une rivale devenue voisine","blocks":[{"text":"San Diejuana porte encore l’héritage de la Loge de Tijuana, vaincue par Los Angeles dans la lutte pour déterminer quelle cité deviendrait le centre magique de la Grande Californie. La défaite a mis fin à la guerre locale sans effacer les rivalités ni les fidélités anciennes.","type":null},{"text":"Face à New-York, San Diejuana n’est donc pas une alliée automatique de Los Angeles. Sa position frontalière, son histoire mexicaine et sa propre tradition magique en font une puissance obligée de négocier au cas par cas plutôt qu’un simple relais de la Haute Loge californienne.","type":null}]}],"mage-lodges::loge-las-vegas":[{"title":"Une puissance périphérique","blocks":[{"text":"La Loge de Las Vegas appartient au nouvel espace californien sans avoir été au centre du duel entre Los Angeles et Tijuana. Cette position lui laisse davantage de distance vis-à-vis de la querelle de légitimité qui déchire les anciennes Hautes Loges.","type":null},{"text":"Elle sert naturellement de point de contact à des Mages qui ne veulent ni se placer sous l’autorité quotidienne de Los Angeles ni rejoindre les réseaux hostiles de New-York. Cette autonomie relative ne signifie pas neutralité : dans le monde des Loges, rester en dehors d’un camp est déjà une position politique.","type":null}]}],"mage-lodges::loge-phoenix":[{"title":"Pôles de population","blocks":[{"text":"Une des caractéristiques de Phoenix est sa concentration en Mages d’origine Coréenne ou, plus généralement, asiatique, en raison des derniers conflits.","type":null}]},{"title":"Une diaspora devenue tradition","blocks":[{"text":"L’arrivée de Mages ayant fui les affrontements asiatiques a donné à Phoenix une identité que les autres Loges californiennes ne possèdent pas. Des pratiques, des lignées d’enseignement et des rancœurs issues de la guerre de Corée s’y sont mêlées aux traditions américaines locales.","type":null},{"text":"Cette concentration a fait de Phoenix un refuge autant qu’un conservatoire : les Mages qui s’y installent ne partagent pas tous la même origine, mais beaucoup ont en commun la mémoire de Loges détruites, absorbées ou soumises par celle de Séoul.","type":null}]}],"mage-lodges::loge-grande-reserve":[{"title":"Une Loge sur un territoire autonome","blocks":[{"text":"La Loge de la Grande Réserve évolue dans un territoire dont les institutions, les communautés et les rapports à la souveraineté diffèrent profondément de ceux des grandes métropoles californiennes. Elle ne peut donc fonctionner comme une simple antenne de Los Angeles.","type":null},{"text":"Ses Mages doivent composer avec les autorités locales et avec des traditions spirituelles qui ne se confondent pas avec la magie des Mageius. Cette proximité crée des échanges, mais aussi une prudence constante : la Loge n’a ni vocation ni légitimité à parler au nom des nations amérindiennes de la Réserve.","type":null}]}],"mage-lodges::autres-loges":[{"title":"Réseaux périphériques et renégats","blocks":[{"text":"Toutes les communautés de Mages ne se reconnaissent pas dans le jeu des cinq Grandes Loges. Portland, la Loge d’Écume et diverses Loges renégates forment des réseaux plus petits, parfois temporaires, parfois durablement constitués autour d’une tradition, d’un maître ou d’un refus de l’ordre établi.","type":null},{"text":"Ces groupes sont difficiles à cartographier parce qu’ils cultivent la même discrétion que les Grandes Loges sans leur stabilité institutionnelle. Certains cherchent seulement à rester indépendants ; d’autres accueillent des Mages en rupture, des survivants de conflits occultes ou des praticiens dont les méthodes les ont rendus indésirables ailleurs.","type":null}]}]};
const TEXT_REPLACEMENTS={"angelus::elynea":[["Origine dans le dossier primaire","Origine divine"],["CONTRADICTION EXPLICITE : Vérité V7 donne désormais à Elynea deux mères — la Déesse de la Lumière et la Déesse de la Vengeance — ainsi qu’un Éon de Gaerras lié à l’Invincibilité. La filiation Denilia/Keden de ce dossier ne peut donc pas être intégrée telle quelle sans arbitrage.","À statuer : deux filiations incompatibles coexistent pour Elynea. Une tradition lui donne deux mères — la Déesse de la Lumière et la Déesse de la Vengeance — ainsi qu’un Éon de Gaerras lié à l’Invincibilité ; une autre la rattache à Denilia et Keden."]],"angelus::yeux-ailes":[["Vérité V7 confirme la progression Angelus = 1 paire, Chérubin = 2 paires, Séraphin = 3 paires. Les mécaniques chiffrées en commentaire de marge du PDF primaire sont volontairement exclues de cette preview Lore.","Les Angelus portent une paire d’ailes, les Chérubins deux et les Séraphins trois. Les anciennes quantifications marginales associées à cette progression ne sont pas retenues."]],"angelus::kabbalistes-sephiriens":[["Vérité V7 confirme que les Kabbalistes peuvent exploiter individuellement les dix Sephiroth sans porter la marque naturelle d’un Angelus et maintient le Sephirien hors progression PJ. Le sacrifice d’un daemon correspondant à chaque Sephira n’y est pas réaffirmé explicitement.","Les Kabbalistes peuvent exploiter individuellement les dix Sephiroth sans porter la marque naturelle d’un Angelus. Les Sephiriens restent hors de la progression ordinaire ; le sacrifice d’un daemon correspondant à chaque Sephira demeure à statuer."]],"angelus::sephira-hokhma":[["Le dossier primaire emploie plusieurs variantes orthographiques entre sa liste des Sephiroth et ses titres de sections (par ex. Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle). Conserver la variante canonique récente lors de l’intégration finale.","Les noms des Archanges connaissent plusieurs variantes traditionnelles — Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle — sans changer l’identité des entités concernées."]],"angelus::sephira-gueburah":[["Le dossier primaire emploie plusieurs variantes orthographiques entre sa liste des Sephiroth et ses titres de sections (par ex. Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle). Conserver la variante canonique récente lors de l’intégration finale.","Les noms des Archanges connaissent plusieurs variantes traditionnelles — Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle — sans changer l’identité des entités concernées."]],"angelus::sephira-hod":[["Le dossier primaire emploie plusieurs variantes orthographiques entre sa liste des Sephiroth et ses titres de sections (par ex. Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle). Conserver la variante canonique récente lors de l’intégration finale.","Les noms des Archanges connaissent plusieurs variantes traditionnelles — Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle — sans changer l’identité des entités concernées."]],"angelus::sephira-yessod":[["Le dossier primaire emploie plusieurs variantes orthographiques entre sa liste des Sephiroth et ses titres de sections (par ex. Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle). Conserver la variante canonique récente lors de l’intégration finale.","Les noms des Archanges connaissent plusieurs variantes traditionnelles — Gabriel/Gabrielle, Michael/Michel, Uriel/Urielle, Camael/Camaelle — sans changer l’identité des entités concernées."]],"angelus::angelus-daemons":[["Le corpus Vérité récent développe davantage l’autonomie individuelle des Angelus incarnés et leur rapport complexe aux humains. La formulation très absolue du dossier primaire sur le désintérêt des Archanges pour « le reste des humains » doit donc être recroisée avant intégration finale.","Les Angelus incarnés conservent une autonomie individuelle réelle et un rapport complexe aux humains. L’idée d’un désintérêt absolu des Archanges pour « le reste des humains » est donc trop générale pour être retenue telle quelle."]],"angelus::autres-archanges":[["Vérité V7 confirme l’existence d’Archanges renégats et de dix Sephiroth, mais ne reprend pas explicitement la classification numérique « 4 grands + 2 déchus + 4 supérieurs » dans son cadrage actuel.","La hiérarchie admet dix Sephiroth et des Archanges renégats. Le découpage « 4 grands + 2 déchus + 4 supérieurs » n’est pas assez stable pour servir de classification définitive."]],"angelus::archanges-renegats":[["Vérité V7 confirme explicitement que « Renégat » ne signifie pas automatiquement traître et que ces Archanges peuvent servir de réserve si un Gardien disparaît.","« Renégat » ne signifie pas automatiquement traître. Certains Archanges renégats restent des réserves possibles si un Gardien disparaît."]],"angelus::serviteurs-renegats":[["CONTRADICTION MÉCANIQUE EXPLICITE : Vérité V7 établit désormais qu’un Angelus lié à un Archange renégat reste lié à cet Archange unique, ne gagne pas le Don du Gardien actuel, et que le Sephira ouvert par le Gardien sert seulement de relais au Don du Renégat. La phrase du dossier primaire accordant « deux dons archangéliques » est donc obsolète comme règle actuelle.","Un Angelus lié à un Archange renégat reste lié à cet Archange unique. Il ne gagne pas le Don du Gardien actuel : le Sephira ouvert par le Gardien sert seulement de relais au Don du Renégat. L’ancienne idée de « deux dons archangéliques » est abandonnée."]],"anti-systemes::anti-systemes":[["Cross-audit : la définition ancienne du Crawler comme renégat par défaut doit rester distincte du cadrage récent de Réalité V9.","Le mot « Crawler » a longtemps servi à désigner presque tout renégat de l’Underlife ; en 2035, son usage est plus précis et ne recouvre pas automatiquement toute forme de dissidence."]],"aseryn-temples::aseryns-lignees":[["Le dossier titre cette période « L’Âge des Fondateurs (les Treize) », puis écrit explicitement « Les fondateurs étaient au nombre de quatorze » et en énumère quatorze. Aucun arbitrage n’est fait dans cette passe.","À statuer : l’Âge des Fondateurs est traditionnellement appelé « les Treize », alors que quatorze Fondateurs sont également énumérés. Les deux décomptes coexistent."]],"corporations::contexte-general":[["Le document source est explicitement marqué « inachevé ». Réalité V9 confirme le poids des corporations en 2035, mais précise qu’en Californie leur autonomie n’est jamais absolue et qu’elles doivent composer avec le droit californien, le CSCO et le CBAC. À conserver comme contrôle canonique lors de la recette.","En 2035, les corporations pèsent lourdement sur l’économie et les institutions, mais leur autonomie n’est jamais absolue en Grande Californie : elles doivent composer avec le droit californien, le CSCO et le CBAC."]],"crawlers::crawlers-organisation-generale":[["Dans le document, les crawlers seront appelés par la première catégorie les représentants, par exemples il y aura les « Fixers » qui comprennent « les fixers », les « streetrackers » et les « hookers », ces trois sous-catégories sont toutes des formes de « fixers » bien que leurs spécificités soient légèrement différentes.","Dans l’Underlife, le nom d’une grande famille sert souvent à désigner l’ensemble de ses variantes. Les « Fixers » regroupent ainsi plusieurs sous-catégories — fixers, streetrackers, hookers ou gunwatchers selon les réseaux — dont les frontières restent souples et parfois contradictoires."],["Cross-audit Création de Personnage V12 : les Fixers restent explicitement cités comme Crawlers dans le lore, mais les Styles jouables listés sont Deathrunner / Merc, Neurodiver, Meditech, Gundriver et NeoPunk. Aucun Style Fixer séparé n’y apparaît. À confirmer avant canonisation.","Les Fixers existent bien comme grande famille crawler, mais la taxonomie des Styles modernes distingue surtout Deathrunner/Merc, Neurodiver, Meditech, Gundriver et NeoPunk ; la place exacte de « Fixer » comme Style autonome reste à statuer."]],"crawlers::fixers-organisation":[["Incohérence interne du document : la synthèse finale des sous-catégories cite « fixers », « streetrackers » et « hookers », alors que les sections et réseaux développés dans le dossier utilisent « fixers », « hookers » et « gunwatchers ». À statuer sans correction silencieuse.","À statuer : une synthèse nomme « fixers », « streetrackers » et « hookers », tandis que les réseaux développés utilisent « fixers », « hookers » et « gunwatchers »."]],"extrals-groups::factions-extrals":[["Les étapes sont évoquées dans un fichier dédié.","Cette reconstruction lente, d’abord sombre puis féodale, a profondément marqué les institutions et les réflexes politiques de l’Humanité galactique."]],"gouvernement::cabinet-presidentiel":[["(cf. fichier sur les agences)","Le détail de leurs opérations relève du réseau des agences californiennes, avec lesquelles le cabinet travaille au quotidien."]],"gouvernement::mairies":[["(La police est définie dans un autre fichier quant à elle.)","La police constitue un appareil exécutif distinct, lié aux mairies et au ministère de la Sécurité intérieure plutôt qu’au fonctionnement ordinaire des services municipaux."]],"grands-exiles::grands-exiles":[["Ce document cherche à lister les principales factions que l’on peut croiser en Grande Californie, en 2035.","En Grande Californie, les Exilés se rassemblent surtout autour de quelques grandes factions capables de protéger leurs communautés, négocier avec les puissances locales et maintenir des liens entre peuples issus de mondes différents."]],"pegre::pegre-californienne":[["La chronologie donne l’éruption de l’Etna en 2023, tandis qu’un passage de contexte la place « aux alentours de 2022 » : à arbitrer avec le corpus Réalité récent.","À statuer : l’éruption de l’Etna est datée de 2023 dans la chronologie, mais une autre tradition la situe autour de 2022."]],"pegre::menorah":[["Nomenclature à verrouiller : Yiddish Connection Second Generation (YC2), New Yiddish Californian Connection (NYCC) et « Menorah » coexistent dans la source.","YC2, NYCC et « Menorah » désignent le même ensemble selon les interlocuteurs ; la nomenclature officielle reste à verrouiller."]],"pegre::french-connection":[["Nomenclature à verrouiller : French Connection, New French Connection (NFC) et « Le Milieu » coexistent dans la source.","French Connection, New French Connection (NFC) et « Le Milieu » désignent la même continuité criminelle à des époques ou dans des milieux différents ; la nomenclature finale reste à verrouiller."]],"pegre::crips":[["La source nomme Chris STANLEY comme ancien chef mort puis le réemploie comme chef des chefs : incohérence interne à statuer avant publication canonique.","À statuer : Chris STANLEY est à la fois donné comme ancien chef mort et cité ensuite comme chef des chefs."]],"pegre::gangs":[["et sont donc abordés en fin de document.","et forment une couche distincte de l’Underlife, à la frontière du crime organisé sans en reprendre les structures classiques."],["qui ont leur propre document dédié (cf. « TUC_organisations_crawlers »).","qui existent aussi en dehors des réseaux mafieux et obéissent à leurs propres logiques de contrats, de survie et de réputation."]],"pelages::pelages-concept":[["Le dossier parle d’« un des cinq chefs des Pelages » alors qu’il décrit six Pelages majeurs. Vérité V7 retient explicitement six traditions : Gris, Sombre/Noir, Roux, Blanc, Brun et Doré.","À statuer : une tradition parle de cinq chefs alors que six Pelages majeurs sont reconnus — Gris, Sombre/Noir, Roux, Blanc, Brun et Doré."]],"plagues::mloxol-vaagor":[["Texte source","Nature et origines"]],"plagues::uxsharith-bellatheis":[["Texte source","Nature et origines"]],"plagues::vhodhal-nactru":[["Texte source","Nature et origines"]],"plagues::cthath-vhadhi":[["Texte source","Nature et origines"]],"plagues::gajh-shaoggith":[["Texte source","Nature et origines"]],"plagues::kthuhuthlul":[["Texte source","Nature et origines"]],"plagues::delanial":[["Texte source","Nature et origines"]],"police::laus-contexte":[["La chronologie place l’éruption de l’Etna en 2023. Le chantier Pègre conserve déjà ce point comme divergence à statuer avec d’autres formulations du corpus.","À statuer : l’éruption de l’Etna est datée de 2023 dans la chronologie, tandis qu’une autre tradition la situe autour de 2022."],["SII / SIII : les deux formes coexistent dans le fichier pour désigner la réforme « Surveillance – Investigation – Intervention ». À harmoniser.","SII et SIII coexistent encore pour désigner la réforme « Surveillance – Investigation – Intervention » ; l’appellation doit être harmonisée."]],"police::concours":[["Plusieurs phrases utilisent encore « LAPD » dans des passages postérieurs à la création du LAUS ; elles sont conservées comme texte source et devront être harmonisées seulement après arbitrage.","L’ancienne appellation LAPD subsiste encore dans certains usages postérieurs à la création du LAUS ; elle peut être comprise comme une survivance terminologique tant que son statut exact n’est pas tranché."]],"police::organisation-sii":[["Le document présente Franklin BENTLEY comme chef adjoint dans l’effectif, alors que la fiche personnage suivante porte par erreur « Robert HAMILTON » sous l’intitulé chef-adjoint ; la fiche personnage est exclue et la contradiction reste à traiter côté Personnages.","À statuer : Franklin BENTLEY est donné comme chef adjoint dans l’effectif, tandis que Robert HAMILTON apparaît ailleurs sous le même intitulé."]],"police::ghost-bureau":[["Le « Ghost Bureau » est présenté comme officiellement inexistant. Son contenu est conservé comme lore institutionnel clandestin, distinct des fiches de personnages.","Le Ghost Bureau est officiellement inexistant. Son activité relève d’un appareil clandestin d’infiltration et d’observation, séparé des unités reconnues du LAUS."]],"police::special-operations":[["Les passages sur les « provocateurs » décrivent des pratiques particulièrement autoritaires. Ils restent collés tels quels et doivent être recroisés avec le canon Réalité récent avant intégration définitive.","Les « provocateurs » décrivent une pratique particulièrement autoritaire, dont la compatibilité avec le droit californien de 2035 reste à statuer."]],"police::grande-californie":[["L’ICUS est décrite ici comme un projet officieux et sérieusement envisagé, pas comme une structure déjà généralisée.","L’ICUS demeure en 2035 un projet officieux et sérieusement envisagé, pas une structure déjà généralisée."]],"police::polices-nord-ouest":[["SII / SIII : les deux formes coexistent dans les notices des polices de Grande Californie. À harmoniser.","SII et SIII coexistent encore dans les appellations des polices de Grande Californie ; l’usage doit être harmonisé."]],"police::polices-sud-est":[["Mexicali est intitulée « MUS » dans le sommaire et le titre, mais « MUF » dans la première phrase de sa notice.","À statuer : Mexicali est appelée « MUS » dans son titre mais « MUF » dans une autre occurrence."],["La notice de Tucson écrit « Tucson est une ville du Nevada » alors que le titre la place dans l’ancien état d’Arizona. Contradiction laissée à statuer.","À statuer : Tucson est située en Arizona dans l’organisation générale, mais une autre mention la place au Nevada."]],"religions::christianisme-organisation":[["À statuer : le PDF détaillé énumère 12 ministères mais indique aussi qu’un lieu peut compter « jusqu’à 9 religieux séculiers (un par ministère) ».","À statuer : la Chrétienté unifiée compte douze ministères, alors qu’un lieu de culte est aussi décrit comme pouvant recevoir jusqu’à neuf religieux séculiers — un par ministère."]],"religions::shientaoisme-informations":[["C’est dans le corpus de textes retenus que les principaux changements s’opèrent, dans les noms des esprits, des dieux, il y a eu une uniformisation des appellations quand elles ont été gardées.","Les principaux changements portent sur les noms des esprits et des dieux : les appellations conservées ont été largement uniformisées afin de permettre à des traditions régionales différentes de partager un même vocabulaire religieux."]],"supernatural-species::autres-creatures":[["les peuples civilisés présentés dans le document, « Garous », « Vampires », « Mages », « Atlantes », « Démons » et « Anges »","les grands peuples organisés de la Vérité — Garous, Vampires, Mages, Atlantes, Démons et Anges —"]],"therianthropes::therianthropes-general":[["Le document contient plusieurs fiches de personnages Aseryns manifestement utilisées comme placeholders sous des rubriques de peuples thérianthropes. Elles sont exclues de cette passe Lore.","Les lignées Khinae sont plus nombreuses et plus structurées que cette vue d’ensemble ; les catégories présentées ici décrivent surtout les familles les plus visibles."]],"vampire-courts::cours-vampiriques":[["Vérité V7 confirme les cinq grandes Cours utilisées ici et précise que l’Empreinte de Cour est liée à l’origine vampirique, pas nécessairement à l’allégeance actuelle.","Les cinq grandes Cours restent le cadre de référence. L’Empreinte de Cour dépend de l’origine vampirique et ne correspond pas nécessairement à l’allégeance actuelle d’un vampire."]]};
