function rootFor(doc){return doc.querySelector('#content,.content')||doc.body;}
function createSection(doc,spec){const section=doc.createElement('section');section.className='preview-section section';section.dataset.loreEnrichmentSection='1';const h=doc.createElement('h2');h.textContent=spec.title||'';section.appendChild(h);for(const block of spec.blocks||[]){const p=doc.createElement('p');p.className=`body-p${block.type==='list'?' list':''}`;p.textContent=block.text||'';section.appendChild(p);}return section;}
function replaceSections(doc,root,sections){root.querySelectorAll(':scope > .preview-section,:scope > .section').forEach(node=>node.remove());root.querySelectorAll(':scope > .notice').forEach(node=>{if(/dossier primaire|fiches individuelles|contenu détaillé/i.test(node.textContent||''))node.remove();});const foot=root.querySelector(':scope > .preview-foot');for(const spec of sections){const section=createSection(doc,spec);if(foot)root.insertBefore(section,foot);else root.appendChild(section);}}
function replaceText(root,pairs){if(!pairs?.length)return;const filter=root.ownerDocument.defaultView?.NodeFilter?.SHOW_TEXT??4;const walker=root.ownerDocument.createTreeWalker(root,filter);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){let value=node.nodeValue||'',next=value;for(const [from,to] of pairs){if(from&&next.includes(from))next=next.split(from).join(to);}if(next!==value)node.nodeValue=next;}}
function removeMeta(root,fragments){if(!fragments?.length)return;for(const fragment of fragments){const candidates=[...root.querySelectorAll('.flag-box,.notice,.canon-box')];for(const node of candidates){if((node.textContent||'').includes(fragment)){node.remove();break;}}}}
export function applyLoreEnrichment(doc,key){const root=rootFor(doc);if(!root||!key)return false;const sections=SECTION_PATCHES[key];if(sections)replaceSections(doc,root,sections);removeMeta(root,REMOVE_FRAGMENTS[key]);replaceText(root,TEXT_REPLACEMENTS[key]);root.dataset.loreEnrichmentKey=key;return Boolean(sections||TEXT_REPLACEMENTS[key]?.length||REMOVE_FRAGMENTS[key]?.length);}
export const loreEnrichmentStats=Object.freeze({sectionPages:Object.keys(SECTION_PATCHES).length,textPages:Object.keys(TEXT_REPLACEMENTS).length,cleanupPages:Object.keys(REMOVE_FRAGMENTS).length});
